def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    opp_c = 0
    opp_d = 0
    my_c = 0
    my_d = 0
    for i in range(n):
        a = history[i][0]
        b = history[i][1]
        if a == 'C':
            my_c += 1
        else:
            my_d += 1
        if b == 'C':
            opp_c += 1
        else:
            opp_d += 1

    prior = opp_c / float(n)

    cC = 0
    dC = 0
    cD = 0
    dD = 0
    rcC = 0
    rdC = 0
    rcD = 0
    rdD = 0

    for i in range(1, n):
        prev_my = history[i - 1][0]
        cur_opp = history[i][1]
        if prev_my == 'C':
            if cur_opp == 'C':
                cC += 1
                if i >= n - 10:
                    rcC += 1
            else:
                dC += 1
                if i >= n - 10:
                    rdC += 1
        else:
            if cur_opp == 'C':
                cD += 1
                if i >= n - 10:
                    rcD += 1
            else:
                dD += 1
                if i >= n - 10:
                    rdD += 1

    last_my = history[-1][0]
    last_opp = history[-1][1]

    totalC = cC + dC
    totalD = cD + dD
    recentC = rcC + rdC
    recentD = rcD + rdD

    last_D_resp = None
    for i in range(n - 1, 0, -1):
        if history[i - 1][0] == 'D':
            last_D_resp = history[i][1]
            break

    if last_my == 'C':
        count_my = totalC
        c_my = cC
    else:
        count_my = totalD
        c_my = cD

    if count_my > 0:
        p = c_my / float(count_my)
        if count_my < 3:
            p = 0.75 * p + 0.25 * prior
    else:
        p = prior

    if totalD == 0:
        if last_my == 'D':
            if opp_d * 2 > n:
                return 'D'
            return 'C'
        if prior <= 0.40:
            return 'D'
        if opp_d == 0 and n >= 8:
            return 'D'
        if n == 10 and prior <= 0.75:
            return 'D'
        if (n == 15 or n == 35 or n == 70) and opp_d <= 2:
            return 'D'
        if n == 20 and opp_d * 5 <= n:
            return 'D'
        return 'C'

    prelim_qC = cC / float(totalC) if totalC > 0 else prior

    qD = cD / float(totalD)
    if recentD > 0:
        qD_recent = rcD / float(recentD)
        if recentD >= 3:
            qD = 0.55 * qD + 0.45 * qD_recent
        else:
            qD = 0.8 * qD + 0.2 * qD_recent

    if last_D_resp == 'D':
        if recentD <= 4:
            qD = min(qD, 0.25)
        else:
            qD = min(qD, 0.45)
    elif last_D_resp == 'C':
        if totalD <= 2 and recentD <= 2:
            qD = max(qD, 0.75)

    if prelim_qC < 0.75:
        if totalD <= 2:
            if qD < prelim_qC:
                qD = prelim_qC
        elif totalD <= 5:
            blended = 0.6 * qD + 0.4 * prelim_qC
            if qD < blended:
                qD = blended

    if totalC > 0:
        qC = cC / float(totalC)
        if recentC > 0:
            qC_recent = rcC / float(recentC)
            if recentC >= 3:
                qC = 0.55 * qC + 0.45 * qC_recent
            else:
                qC = 0.8 * qC + 0.2 * qC_recent
    else:
        qC = prior

    future = 100 - n - 1
    scoreC = 3.0 * p + float(future) * (1.0 + 2.0 * qC)
    scoreD = 1.0 + 4.0 * p + float(future) * (1.0 + 2.0 * qD)

    margin = 0.0
    if qD < 0.35:
        margin = 3.0
    elif qD > 0.75 and last_D_resp == 'C':
        margin = -2.0

    if opp_d > 0 and my_d * 5 > n * 3 and qD > 0.5:
        if margin < 2.0:
            margin = 2.0

    if scoreD > scoreC + margin:
        return 'D'
    return 'C'
